// Group-128 BF16 to FP8 quantization with group-major scales and row-band traversal.
// SPDX-License-Identifier: MIT
// Copyright (C) 2024-2026, Advanced Micro Devices, Inc. All rights reserved.
#include <ATen/hip/HIPContext.h>
#include <hip/hip_runtime.h>
#include <torch/library.h>
#include <cstdint>

namespace {
using words8 = uint32_t __attribute__((ext_vector_type(8)));
using words4 = uint32_t __attribute__((ext_vector_type(4)));

template<int Threads, int BandRows>
__global__ __launch_bounds__(Threads)
void quantize_groups(const uint16_t* __restrict__ x, uint8_t* __restrict__ y,
                     float* __restrict__ scales, int rows, int columns) {
    constexpr int groups_per_block = Threads / 4;
    const int lane = threadIdx.x & 3;
    const int local_group = threadIdx.x / 4;
    const int groups = columns / 128;
    int row, column;
    if constexpr (BandRows != 0) {
        constexpr int band_columns = groups_per_block / BandRows;
        const int column_tiles = groups / band_columns;
        row = (blockIdx.x / column_tiles) * BandRows + local_group % BandRows;
        column = (blockIdx.x % column_tiles) * band_columns + local_group / BandRows;
    } else {
        const int group = blockIdx.x * groups_per_block + local_group;
        row = group / groups;
        column = group % groups;
    }
    if (row >= rows) return;

    float values[32];
    const int64_t base = int64_t(row) * columns + column * 128;
#pragma unroll
    for (int chunk = 0; chunk < 2; ++chunk) {
        const int offset = BandRows ? (lane + 4 * chunk) * 16 : lane * 32 + chunk * 16;
        const words8 words = *reinterpret_cast<const words8*>(x + base + offset);
#pragma unroll
        for (int j = 0; j < 8; ++j) {
            values[chunk * 16 + 2 * j] = __builtin_bit_cast(float, words[j] << 16);
            values[chunk * 16 + 2 * j + 1] = __builtin_bit_cast(float, words[j] & 0xffff0000u);
        }
    }
    float maximum = 1e-10f;
#define MAX_PAIR(a, b) "v_maximum3_f32 %0, %0, |%" #a "|, |%" #b "|\n\t"
#pragma unroll
    for (int chunk = 0; chunk < 2; ++chunk) {
        const float* v = values + chunk * 16;
        asm(MAX_PAIR(1, 2) MAX_PAIR(3, 4) MAX_PAIR(5, 6) MAX_PAIR(7, 8)
            MAX_PAIR(9, 10) MAX_PAIR(11, 12) MAX_PAIR(13, 14) MAX_PAIR(15, 16)
            : "+v"(maximum)
            : "v"(v[0]), "v"(v[1]), "v"(v[2]), "v"(v[3]),
              "v"(v[4]), "v"(v[5]), "v"(v[6]), "v"(v[7]),
              "v"(v[8]), "v"(v[9]), "v"(v[10]), "v"(v[11]),
              "v"(v[12]), "v"(v[13]), "v"(v[14]), "v"(v[15]));
    }
#undef MAX_PAIR
    maximum = fmaxf(maximum, __shfl_xor(maximum, 1));
    maximum = fmaxf(maximum, __shfl_xor(maximum, 2));
    const float scale = maximum * (1.0f / 448.0f);
    if (lane == 0) scales[int64_t(column) * rows + row] = scale;
    const float r = __builtin_amdgcn_rcpf(scale);
    const float correction = __builtin_fmaf(-scale, r, 1.0f);
    const float inverse = __builtin_fmaf(correction, r, r);
#pragma unroll
    for (int chunk = 0; chunk < 2; ++chunk) {
        words4 packed;
#pragma unroll
        for (int j = 0; j < 4; ++j) {
            const int at = chunk * 16 + j * 4;
            const float a = values[at] * inverse;
            const float b = values[at + 1] * inverse;
            const float c = values[at + 2] * inverse;
            const float d = values[at + 3] * inverse;
            int word = __builtin_amdgcn_cvt_pk_fp8_f32(a, b, __builtin_bit_cast(int, a), false);
            packed[j] = __builtin_amdgcn_cvt_pk_fp8_f32(c, d, word, true);
        }
        const int offset = BandRows ? (lane + 4 * chunk) * 16 : lane * 32 + chunk * 16;
        *reinterpret_cast<words4*>(y + base + offset) = packed;
    }
}

template<int Threads, int BandRows>
void launch(const at::Tensor& x, at::Tensor& quantized, at::Tensor& scales) {
    const int rows = x.size(0), columns = x.size(1), groups = columns / 128;
    constexpr int groups_per_block = Threads / 4;
    int blocks;
    if constexpr (BandRows != 0) {
        blocks = ((rows + BandRows - 1) / BandRows) * (groups / (groups_per_block / BandRows));
    } else {
        blocks = (rows * groups + groups_per_block - 1) / groups_per_block;
    }
    quantize_groups<Threads, BandRows><<<blocks, Threads, 0, at::hip::getCurrentHIPStream()>>>(
        static_cast<const uint16_t*>(x.data_ptr()), static_cast<uint8_t*>(quantized.data_ptr()),
        static_cast<float*>(scales.data_ptr()), rows, columns);
}

void run(const at::Tensor& x, at::Tensor& quantized, at::Tensor& scales) {
    const int rows = x.size(0), columns = x.size(1), groups = columns / 128;
    if (rows >= 1024 && groups % 8 == 0) launch<256, 8>(x, quantized, scales);
    else if (rows >= 64 && rows < 1024 && columns <= 8192) launch<64, 16>(x, quantized, scales);
    else if (rows >= 64 && rows < 1024 && groups % 2 == 0) launch<64, 8>(x, quantized, scales);
    else launch<64, 0>(x, quantized, scales);
}
} // namespace

#define TORCH_LIBRARY_EXPAND(ns, m) TORCH_LIBRARY(ns, m)
TORCH_LIBRARY_EXPAND(TORCH_EXTENSION_NAME, m) {
    m.def("run(Tensor x, Tensor(a!) quantized, Tensor(b!) scales) -> ()", &run);
}
